const scope=self.registration.scope;
const prefix='seafarer-pwa:'+scope;
const shellName=prefix+':shell:'+SPEC.release;
const audioName=prefix+':audio:'+SPEC.audioVersion;
const address=a=>new URL(a.path,scope).href;
const shellByURL=new Map(SPEC.shell.map(a=>[address(a),a]));
const audioByURL=new Map(SPEC.audio.map(a=>[address(a),a]));
const sha=async data=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(b=>b.toString(16).padStart(2,'0')).join('');
async function verified(response,asset){
  if(!response||response.status!==200)return null;
  const data=await response.arrayBuffer();
  return data.byteLength===asset.bytes&&await sha(data)===asset.sha256?data:null;
}
async function acquire(cache,asset){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
  try{
    const response=await fetch(address(asset),{cache:'no-store',credentials:'same-origin',signal:controller.signal});
    const data=await verified(response,asset);
    if(!data)throw new Error('檔案缺失或校驗不符：'+asset.path);
    await cache.put(address(asset),new Response(data,{status:200,headers:{'Content-Type':asset.type,'Content-Length':String(data.byteLength)}}));
    if(!await verified(await cache.match(address(asset)),asset))throw new Error('儲存後讀回校驗失敗：'+asset.path);
  }finally{clearTimeout(timer);}
}
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(shellName);
  for(const asset of SPEC.shell)if(!await verified(await cache.match(address(asset)),asset))await acquire(cache,asset);
  // Deliberately no skipWaiting: new versions wait for an explicit user action.
})()));
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
// Keep old release caches and quiz storage intact. No clear/delete migration.
let job=null,paused=false;
async function publish(state){
  for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))if(client.url.startsWith(scope))client.postMessage({type:'PWA_STATUS',state});
}
let last={release:SPEC.release,state:'checking',count:0,total:SPEC.audio.length,totalBytes:SPEC.audio.reduce((n,a)=>n+a.bytes,0)};
async function inspect(progress){
  const shell=await caches.open(shellName),audio=await caches.open(audioName);let shellOK=true,count=0;const missing=[];
  for(const a of SPEC.shell)if(!await verified(await shell.match(address(a)),a))shellOK=false;
  for(const a of SPEC.audio){if(await verified(await audio.match(address(a)),a))count++;else missing.push(a);if((count+missing.length)%30===0)progress?.({...last,state:'checking',count});}
  last={...last,state:shellOK&&count===SPEC.audio.length?'ready':'partial',count,shellOK,message:undefined};
  return {state:last,missing};
}
async function download(progress){
  paused=false;const checked=await inspect(progress),cache=await caches.open(audioName);
  if(!checked.state.shellOK){const shell=await caches.open(shellName);for(const a of SPEC.shell)if(!await verified(await shell.match(address(a)),a))await acquire(shell,a);}
  last={...checked.state,state:'downloading'};progress(last);let cursor=0,failure=null;
  async function runner(){
    while(!paused&&!failure&&cursor<checked.missing.length){const asset=checked.missing[cursor++];
      try{await acquire(cache,asset);last={...last,state:'downloading',count:last.count+1};progress(last);}catch(e){failure=e;}
    }
  }
  await Promise.all([runner(),runner(),runner()]);
  if(failure){last={...last,state:'error'};throw failure;}
  const result=(await inspect(progress)).state;
  if(paused&&result.state!=='ready')return {...result,message:`已暫停；${result.count} 個已校驗音檔保留，之後可繼續下載。`};
  return result;
}
self.addEventListener('message',event=>{
  const port=event.ports?.[0];if(!port)return;
  const progress=s=>port.postMessage({progress:s});
  event.waitUntil((async()=>{
    try{
      let result;
      switch(event.data?.type){
        case 'STATUS':result=job?last:(await inspect(progress)).state;break;
        case 'DOWNLOAD':
          if(job){result=last;break;}
          job=download(s=>{progress(s);void publish(s);});try{result=await job;}finally{job=null;}
          await publish(result);break;
        case 'PAUSE':paused=true;result={paused:true};break;
        case 'ACTIVATE':{
          const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});
          if(windows.filter(c=>c.url.startsWith(scope)).length>1)throw new Error('請先關閉其他本網站頁面，再套用更新；成績不會清除。');
          await self.skipWaiting();result={activating:true};break;
        }
        default:throw new Error('未知的離線操作');
      }
      port.postMessage({ok:true,result});
    }catch(e){
      if(event.data?.type==='DOWNLOAD')await publish({...last,state:'error',message:e.message,errorName:e.name});
      port.postMessage({ok:false,error:e.message,name:e.name});
    }
  })());
});
async function ranged(response,range){
  if(!range)return response;
  const data=await response.arrayBuffer(),length=data.byteLength,m=/^bytes=(\d*)-(\d*)$/.exec(range);
  let start,end;
  if(m&&(m[1]||m[2])){
    if(!m[1]){const suffix=Number(m[2]);start=Math.max(0,length-suffix);end=length-1;}
    else{start=Number(m[1]);end=m[2]?Math.min(Number(m[2]),length-1):length-1;}
  }
  if(!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start<0||start>=length||end<start)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+length}});
  return new Response(data.slice(start,end+1),{status:206,headers:{'Content-Type':'audio/mpeg','Content-Range':`bytes ${start}-${end}/${length}`,'Content-Length':String(end-start+1),'Accept-Ranges':'bytes'}});
}
self.addEventListener('fetch',event=>{
  const request=event.request;if(request.method!=='GET')return;
  const url=new URL(request.url),clean=url.origin+url.pathname;
  if(request.mode==='navigate'&&(clean===scope||clean===new URL('index.html',scope).href)){
    event.respondWith((async()=>{const c=await caches.open(shellName);return await c.match(new URL('index.html',scope).href)||fetch(request);})());return;
  }
  if(audioByURL.has(clean)){
    event.respondWith((async()=>{const c=await caches.open(audioName),r=await c.match(clean);return r?ranged(r,request.headers.get('Range')):fetch(request);})());return;
  }
  if(shellByURL.has(clean))event.respondWith((async()=>{const c=await caches.open(shellName);return await c.match(clean)||fetch(request);})());
});
